  const handleGoogleSignIn = async () => {
    try {
      setRecaptchaVerifying(true);
      setLoading(true);

      const token = await executeRecaptcha("login_google");
      if (!token) {
        alert(
          "Eroare de securitate reCAPTCHA Enterprise: Verificarea anti-bot a eșuat. Vă rugăm să reîncercați.",
        );
        setRecaptchaVerifying(false);
        setLoading(false);
        return;
      }

      try {
        const verifyRes = await fetch("/api/verify-recaptcha", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ token, expectedAction: "login_google" })
        });
        const verifyData = await verifyRes.json();
        if (!verifyData.success) {
          alert(
            "Verificarea de securitate reCAPTCHA Enterprise a raportat activitate suspectă sau eșuată. Acces interzis."
          );
          setRecaptchaVerifying(false);
          setLoading(false);
          return;
        }
      } catch (verifyErr) {
        console.warn("Eroare la apelarea serviciului de verificare reCAPTCHA:", verifyErr);
      }

      setRecaptchaVerifying(false);
      await setPersistence(auth, browserLocalPersistence).catch(() => {
        return setPersistence(auth, browserSessionPersistence).catch(() => {});
      });
      const provider = new GoogleAuthProvider();
      provider.setCustomParameters({ prompt: "select_account" });
      await signInWithPopup(auth, provider);
    } catch (err: any) {
      console.error("Google Auth Error:", err);
      if (
        err?.code === "auth/popup-closed-by-user" ||
        err?.code === "auth/cancelled-popup-request" ||
        err?.code === "auth/user-cancelled"
      ) {
        return;
      }
      alert("Conectarea cu Google a eșuat. Vă rugăm să încercați din nou.");
    } finally {
      setRecaptchaVerifying(false);
      setLoading(false);
    }
  };

