  const statsData = useMemo(() => {
    let totalPatients = 0;
    let consultatiiCompleteCount = 0;
    let reveniriCount = 0;
    let ochelariCount = 0;
    let doarTratamentCount = 0;
    let alteCount = 0;

    appointments.forEach((app) => {
      if (app.status === "cancelled") return;

      if (adminStatsDoctor !== "all" && app.doctorId !== adminStatsDoctor) return;

      if (!app.startTime) return;
      const appDate = new Date(app.startTime);
      const yr = appDate.getFullYear().toString();
      const mo = appDate.getMonth().toString(); // "0" - "11"
      const dayISO = app.startTime.substring(0, 10); // YYYY-MM-DD

      if (adminStatsYear !== "all" && yr !== adminStatsYear) return;

      if (adminStatsMonth !== "all" && mo !== adminStatsMonth) return;

      if (adminStatsDay !== "all") {
        if (adminStatsDay === "today") {
          const todayStr = new Date().toISOString().substring(0, 10);
          if (dayISO !== todayStr) return;
        } else if (dayISO !== adminStatsDay) {
          return;
        }
      }

      totalPatients++;

      const matchingRecord = medicalRecords.find(
        (r) => r.patientName === app.patientName && r.patientPhone === app.patientPhone
      );

      const isControl = !!app.isControl || !!matchingRecord?.isControl;
      const isConsultComplet = !!app.isConsultComplet || !!matchingRecord?.isConsultComplet;

      const hasGlasses = !!matchingRecord?.glassesOrder && (
        !!matchingRecord.glassesOrder.frameCode ||
        !!matchingRecord.glassesOrder.total ||
        (matchingRecord.glassesOrder.od && (!!matchingRecord.glassesOrder.od.sph || !!matchingRecord.glassesOrder.od.cyl)) ||
        (matchingRecord.glassesOrder.os && (!!matchingRecord.glassesOrder.os.sph || !!matchingRecord.glassesOrder.os.cyl))
      );

      const hasTreatment = !!matchingRecord?.treatment?.trim() || !!matchingRecord?.medications?.trim();

      if (isControl) {
        reveniriCount++;
      } else if (isConsultComplet) {
        consultatiiCompleteCount++;
      } else if (hasGlasses) {
        ochelariCount++;
      } else if (hasTreatment) {
        doarTratamentCount++;
      } else {
        alteCount++;
      }
    });

    return {
      totalPatients,
      reveniriCount,
      consultatiiCompleteCount,
      ochelariCount,
      doarTratamentCount,
      alteCount,
      categories: [
        { name: "Sesiuni Control / Reveniri", value: reveniriCount, color: "#a855f7" },
        { name: "Consultații Complete", value: consultatiiCompleteCount, color: "#3b82f6" },
        { name: "Ochelari Comandați", value: ochelariCount, color: "#10b981" },
        { name: "Doar cu Tratament", value: doarTratamentCount, color: "#f59e0b" },
        { name: "Consult Simplu / Altele", value: alteCount, color: "#64748b" }
      ]
    };
  }, [appointments, medicalRecords, adminStatsDoctor, adminStatsYear, adminStatsMonth, adminStatsDay]);
