  const getBirthdayStatus = useCallback(
    (birthDateStr: string | undefined | null) => {
      if (!birthDateStr) return null;

      let birthDate: Date;
      if (birthDateStr.includes("-")) {
        const parts = birthDateStr.split("-");
        if (parts[0].length === 4) {
          birthDate = new Date(
            parseInt(parts[0]),
            parseInt(parts[1]) - 1,
            parseInt(parts[2]),
          );
        } else {
          birthDate = new Date(
            parseInt(parts[2]),
            parseInt(parts[1]) - 1,
            parseInt(parts[0]),
          );
        }
      } else {
        birthDate = new Date(birthDateStr);
      }

      if (isNaN(birthDate.getTime())) return null;

      const today = startOfDay(new Date());
      const bMonth = birthDate.getMonth();
      const bDay = birthDate.getDate();

      const thisYearBday = new Date(today.getFullYear(), bMonth, bDay);
      const nextYearBday = new Date(today.getFullYear() + 1, bMonth, bDay);

      let targetBday = thisYearBday;
      if (
        thisYearBday.getTime() < today.getTime() &&
        !isSameDay(thisYearBday, today)
      ) {
        targetBday = nextYearBday;
      }

      const diffTime = targetBday.getTime() - today.getTime();
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

      const isToday = isSameDay(thisYearBday, today);
      const age = today.getFullYear() - birthDate.getFullYear();

      return {
        isToday,
        daysRemaining: isToday ? 0 : diffDays,
        age: isToday
          ? age
          : age -
            (targetBday.getFullYear() === today.getFullYear() + 1 ? 1 : 0),
        bMonth,
        bDay,
        formattedDate: `${bDay.toString().padStart(2, "0")}.${(bMonth + 1).toString().padStart(2, "0")}`,
      };
    },
    [],
  );

  const generatePatientBirthdayMessage = useCallback(
    (
      patientName: string,
      birthDate?: string | null,
      customTemplate?: string,
    ) => {
      const bStatus = getBirthdayStatus(birthDate);
      const age = bStatus?.age;

      const templateInUse =
        customTemplate !== undefined ? customTemplate : birthdayTemplate;

      let baseTemplate = templateInUse;

      // Default respectful template fallback if template is empty or uses previous default without age
      if (
        !baseTemplate ||
        baseTemplate.trim() === "" ||
        baseTemplate.includes("Echipa noastră vă urează o zi plină de soare, sănătate, fericire și o vedere limpede")
      ) {
        if (age !== undefined && age !== null && age > 0) {
          if (age >= 60) {
            baseTemplate =
              "La mulți ani cu deosebit respect și aleasă prețuire, {nume}! 🎂 Cu ocazia împlinirii frumoasei vârste de {varsta} de ani, echipa noastră vă dorește din tot sufletul multă sănătate, liniște sufletească, bucurii alături de cei dragi și o vedere limpede și senină! Să aveți o zi binecuvântată! 🎈🥂✨";
          } else {
            baseTemplate =
              "La mulți ani cu ocazia împlinirii frumoasei vârste de {varsta} de ani, {nume}! 🎂🥳 Echipa noastră vă dorește o zi plină de soare, sănătate, fericire și o vedere limpede spre toate minunile vieții! Să aveți o zi minunată! 🎈🥂✨";
          }
        } else {
          baseTemplate =
            "La mulți ani frumoși, {nume}! 🎂🥳 Echipa noastră vă dorește o zi plină de soare, sănătate, fericire și o vedere limpede spre toate minunile vieții! Să aveți o zi minunată! 🎈🥂✨";
        }
      }

      // If patient has advanced age (>= 60) and standard template is used, apply respectful wording
      if (age !== undefined && age !== null && age >= 60 && baseTemplate.startsWith("La mulți ani cu ocazia împlinirii frumoasei vârste de {varsta}")) {
        baseTemplate =
          "La mulți ani cu deosebit respect și aleasă prețuire, {nume}! 🎂 Cu ocazia împlinirii frumoasei vârste de {varsta} de ani, echipa noastră vă dorește din tot sufletul multă sănătate, liniște sufletească, bucurii alături de cei dragi și o vedere limpede și senină! Să aveți o zi binecuvântată! 🎈🥂✨";
      }

      // Replace {nume}
      let msg = baseTemplate.replace(/{nume}/g, patientName);

      // Replace {varsta}
      if (age !== undefined && age !== null && age > 0) {
        msg = msg.replace(/{varsta}/g, `${age}`);
      } else {
        msg = msg
          .replace(/cu ocazia împlinirii frumoasei vârste de {varsta} de ani,?\s*/gi, "")
          .replace(/împlinirii frumoasei vârste de {varsta} de ani,?\s*/gi, "")
          .replace(/de {varsta} de ani/gi, "")
          .replace(/{varsta}/gi, "");
      }

      return msg.replace(/\s+/g, " ").replace(/ ,/g, ",").trim();
    },
    [getBirthdayStatus, birthdayTemplate],
  );

