  const formatWhatsAppPhone = (phone: string) => {
    let cleaned = phone.replace(/\D/g, ""); // keep only digits
    if (cleaned.startsWith("0")) {
      cleaned = "40" + cleaned.slice(1);
    } else if (cleaned.length === 9) {
      cleaned = "40" + cleaned;
    }
    return cleaned;
  };

  const getDoctorName = (doctorId: string): string => {
    const doctorObj = availableUsers.find(
      (u) => u.role === doctorId || u.id === doctorId,
    );
    if (doctorObj && doctorObj.name) {
      return doctorObj.name;
    }
    return getRoleLabel(doctorId as Role) || doctorId;
  };

  const generateMessageFromTemplate = (
    template: string,
    patientName: string,
    appointment?: Appointment,
  ): string => {
    let msg = template;
    msg = msg.replaceAll("{pacient}", patientName);

    if (appointment) {
      const appTime = parseISO(appointment.startTime);
      const dateFormatted = format(appTime, "dd.MM.yyyy", { locale: ro });
      const hourFormatted = format(appTime, "HH:mm");
      const drLabel = getDoctorName(appointment.doctorId);

      msg = msg.replaceAll("{data}", dateFormatted);
      msg = msg.replaceAll("{ora}", hourFormatted);
      msg = msg.replaceAll("{medic}", drLabel);
    } else {
      msg = msg.replaceAll("{data}", "---");
      msg = msg.replaceAll("{ora}", "---");
      msg = msg.replaceAll("{medic}", "---");
    }
    return msg;
  };

  const handleOpenWhatsAppModal = (
    patientName: string,
    patientPhone: string,
    appointment?: Appointment,
  ) => {
    if (!patientPhone) {
      alert("Pacientul nu are un număr de telefon salvat!");
      return;
    }
    const phoneClean = patientPhone.replace(/\D/g, "");
    const nameLower = patientName.toLowerCase().trim();
    const now = new Date();

    const futureApps = appointments
      .filter((a) => {
        if (a.status !== "scheduled") return false;
        const aPhoneClean = a.patientPhone.replace(/\D/g, "");
        const aNameLower = a.patientName.toLowerCase().trim();
        const isSamePatient =
          (phoneClean && aPhoneClean === phoneClean) ||
          (nameLower && aNameLower === nameLower);
        return (
          isSamePatient && parseISO(a.startTime).getTime() >= now.getTime()
        );
      })
      .sort(
        (a, b) =>
          parseISO(a.startTime).getTime() - parseISO(b.startTime).getTime(),
      );

    const nextApp = futureApps[0] || appointment;

    setWhatsAppRecipient({ name: patientName, phone: patientPhone });

    let initialTemplate: "next_appointment" | "simple_reminder" | "custom" =
      "simple_reminder";
    let messageText = generateMessageFromTemplate(
      simpleReminderTemplate,
      patientName,
      nextApp,
    );

    if (nextApp) {
      initialTemplate = "next_appointment";
      messageText = generateMessageFromTemplate(
        nextAppointmentTemplate,
        patientName,
        nextApp,
      );
    }

    setWhatsAppTemplateType(initialTemplate);
    setWhatsAppMessageText(messageText);
    setIsWhatsAppModalOpen(true);
  };

  const applyWhatsAppTemplate = (
    type: "next_appointment" | "simple_reminder" | "custom",
    recipientName: string,
    nextApp?: Appointment,
  ) => {
    setWhatsAppTemplateType(type);
    if (type === "next_appointment") {
      setWhatsAppMessageText(
        generateMessageFromTemplate(
          nextAppointmentTemplate,
          recipientName,
          nextApp,
        ),
      );
    } else if (type === "simple_reminder") {
      setWhatsAppMessageText(
        generateMessageFromTemplate(
          simpleReminderTemplate,
          recipientName,
          nextApp,
        ),
      );
    } else {
      setWhatsAppMessageText("");
    }
  };

