  const getRoleLabel = (role: Role | string): string => {
    return (
      roleLabelsState[role as Role] ||
      ROLE_LABELS[role as Role] ||
      (typeof role === "string" ? role : "")
    );
  };

  const getShortDoctorName = (roleOrName: string | Role): string => {
    if (!roleOrName) return "";

    const docStr = roleOrName.toString().toLowerCase();

    if (docStr === "admin" || docStr.includes("optometrist") || docStr.includes("negreanu")) {
      return "Negreanu";
    }
    if (docStr === "doctor1" || docStr.includes("turcanu") || docStr.includes("trucanu") || docStr.includes("irina")) {
      return "Turcanu";
    }
    if (docStr === "doctor2" || docStr.includes("zorila") || docStr.includes("zorilă") || docStr.includes("cristina")) {
      return "Zorila";
    }
    if (docStr === "doctor3" || docStr.includes("ilie") || docStr.includes("larisa")) {
      return "Ilie";
    }

    const fullLabel = getRoleLabel(roleOrName as Role);
    const str = (fullLabel || roleOrName).trim();
    const lower = str.toLowerCase();

    if (lower.includes("turcanu") || lower.includes("trucanu") || lower.includes("irina")) {
      return "Turcanu";
    }
    if (lower.includes("zorila") || lower.includes("zorilă") || lower.includes("cristina")) {
      return "Zorila";
    }
    if (lower.includes("ilie") || lower.includes("larisa")) {
      return "Ilie";
    }
    if (lower.includes("negreanu") || lower.includes("optometrist") || lower.includes("admin")) {
      return "Negreanu";
    }

    let clean = str.replace(/^(dr\.|dr\s+|ing\.|optometrist\s+)/gi, "").trim();
    if (clean.includes(" ")) {
      clean = clean.split(/\s+/)[0];
    }
    return clean || str;
  };

