  const saveRoleLabels = async (
    newLabels: Record<string, string>,
    silent = false,
  ) => {
    try {
      if (!silent) setLoading(true);
      await setDoc(doc(db, "settings", "roleLabels"), newLabels, {
        merge: true,
      });

      for (const [role, newName] of Object.entries(newLabels)) {
        const userToUpdate = availableUsers.find((u) => u.role === role);
        if (userToUpdate && userToUpdate.name !== newName) {
          await setDoc(
            doc(db, "users", userToUpdate.id),
            { name: newName },
            { merge: true },
          );
        }
      }

      if (!silent)
        setSuccessMessage("Numele medicilor au fost actualizate cu succes!");
    } catch (error) {
      console.error("Error saving role labels:", error);
      if (!silent)
        setErrorMessage(
          "Eroare la salvarea numelor medicilor. Verificați conexiunea.",
        );
    } finally {
      if (!silent) setLoading(false);
    }
  };

