  const handleSaveGdpr = async (cnp: string, signatureInput: string, phoneInput?: string): Promise<string | null> => {
    const signature = signatureInput && signatureInput.length > 8000
      ? await compressSignatureDataUrl(signatureInput)
      : signatureInput;
    const name = (
      isMedicalRecordModalOpen && currentMedicalRecord
        ? currentMedicalRecord.patientName
        : patientName
    )?.trim() || "";

    const phone = (
      (phoneInput && phoneInput.trim()) ||
      (isMedicalRecordModalOpen && currentMedicalRecord
        ? currentMedicalRecord.patientPhone
        : patientPhone)
    )?.trim() || "";

    const cnpClean = cnp ? cnp.trim() : "";

    if (!name) {
      return "Numele pacientului este obligatoriu.";
    }

    // CNP validation ONLY if provided
    if (cnpClean.length > 0) {
      if (cnpClean.length !== 13) {
        return "Dacă este completat, CNP-ul trebuie să aibă exact 13 cifre.";
      }
      if (!validateCNP(cnpClean)) {
        return "CNP-ul introdus este invalid (nu respectă cifra de control).";
      }
    }

    // Automatically update global patientPhone state if provided
    if (phone) {
      setPatientPhone(phone);
    }

    const phoneKey = phone || (cnpClean ? `cnp_${cnpClean}` : "fara_tel");
    const recordId = (
      isMedicalRecordModalOpen && currentMedicalRecord
        ? currentMedicalRecord.id
        : `${name}_${phoneKey}`
    ).replace(/\s+/g, "_").toLowerCase();

    // Check duplicate CNP only if provided
    if (cnpClean.length > 0) {
      const duplicate = medicalRecords.find(
        (r) =>
          r.patientCnp &&
          r.patientCnp.trim() === cnpClean &&
          r.id !== recordId
      );

      if (duplicate) {
        return `CNP-ul introdus (${cnpClean}) aparține deja altui pacient: ${duplicate.patientName} (${duplicate.patientPhone || "fără telefon"}).`;
      }
    }

    // Try extracting birth date from CNP if valid 13 digits
    let extractedBirthDate = "";
    if (cnpClean.length === 13) {
      const s = parseInt(cnpClean[0], 10);
      const yy = cnpClean.slice(1, 3);
      const mm = cnpClean.slice(3, 5);
      const dd = cnpClean.slice(5, 7);
      let century = 1900;
      if (s === 1 || s === 2) century = 1900;
      else if (s === 3 || s === 4) century = 1800;
      else if (s === 5 || s === 6) century = 2000;
      const mNum = parseInt(mm, 10);
      const dNum = parseInt(dd, 10);
      if (century > 0 && mNum >= 1 && mNum <= 12 && dNum >= 1 && dNum <= 31) {
        extractedBirthDate = `${century + parseInt(yy, 10)}-${mm}-${dd}`;
      }
    }

    try {
      const existingRecord = medicalRecords.find(
        (r) =>
          r.patientName.toLowerCase().trim() === name.toLowerCase().trim() &&
          (phone ? r.patientPhone.trim() === phone : true)
      );

      const isCurrentActive =
        isMedicalRecordModalOpen &&
        currentMedicalRecord &&
        currentMedicalRecord.patientName.toLowerCase().trim() === name.toLowerCase().trim();

      const baseRecord = isCurrentActive
        ? currentMedicalRecord
        : (existingRecord || {
            id: recordId,
            patientName: name,
            patientPhone: phone,
            patientCnp: cnpClean,
            patientBirthDate: extractedBirthDate || patientBirthDate || "",
            od: { sph: "", cyl: "", axis: "", add: "", pd: "" },
            os: { sph: "", cyl: "", axis: "", add: "", pd: "" },
            dp: "",
            treatment: "",
            specialMentions: "",
          });

      const finalBirthDate = extractedBirthDate || baseRecord.patientBirthDate || patientBirthDate || "";

      const updatedRecord = {
        ...baseRecord,
        id: recordId, // Ensure ID is standardized
        patientPhone: phone || baseRecord.patientPhone || "",
        patientCnp: cnpClean,
        patientBirthDate: finalBirthDate,
        gdprSigned: !!signature,
        gdprSignature: signature,
        gdprSignedAt: signature ? new Date().toISOString() : null,
        updatedAt: new Date().toISOString(),
      };

      await setDoc(doc(db, "medicalRecords", recordId), updatedRecord);

      if (currentMedicalRecord) {
        setCurrentMedicalRecord((prev) => prev ? {
          ...prev,
          patientPhone: phone || prev.patientPhone || "",
          patientCnp: cnpClean,
          patientBirthDate: finalBirthDate,
          gdprSigned: !!signature,
          gdprSignature: signature,
          gdprSignedAt: signature ? new Date().toISOString() : null,
          updatedAt: new Date().toISOString(),
        } : null);
      }

      // Sync phone, CNP, and birth date to any matching appointments for this patient
      const matchingApps = appointments.filter(
        (app) => app.patientName && app.patientName.toLowerCase().trim() === name.toLowerCase().trim()
      );

      for (const app of matchingApps) {
        const needsUpdate =
          (phone && app.patientPhone !== phone) ||
          app.patientCnp !== cnpClean ||
          (finalBirthDate && app.patientBirthDate !== finalBirthDate);

        if (needsUpdate) {
          try {
            await setDoc(
              doc(db, "appointments", app.id),
              {
                ...app,
                ...(phone ? { patientPhone: phone } : {}),
                patientCnp: cnpClean,
                ...(finalBirthDate ? { patientBirthDate: finalBirthDate } : {}),
                updatedAt: new Date().toISOString(),
              },
              { merge: true }
            );
          } catch (e) {
            console.error("Error updating appointment with phone/cnp/birthDate:", e);
          }
        }
      }

      await logActivity(
        "Semnare GDPR",
        `Pacient: ${name}, Telefon: ${phone || 'fără tel'}, CNP: ${cnpClean || 'fără CNP'}`
      );

      return null;
    } catch (error) {
      console.error("Error saving GDPR consent:", error);
      return "A apărut o eroare la salvarea declarației GDPR în baza de date.";
    }
  };

