  const renamePatientEverywhere = async (
    oldName: string,
    newName: string,
    phone?: string,
    cnp?: string,
    oldRecordId?: string,
  ) => {
    const cleanOld = (oldName || "").trim();
    const cleanNew = (newName || "").trim();

    if (!cleanNew) {
      setErrorMessage("Numele pacientului nu poate fi gol!");
      return false;
    }
    if (cleanOld === cleanNew) {
      return true;
    }

    const cleanPhone = (phone || "").trim();
    const cleanCnp = (cnp || "").trim();
    const now = new Date().toISOString();

    // Find the existing medical record in memory with all consultation history
    const matchedOldRec =
      findPatientMedicalRecord(cleanOld, cleanPhone, cleanCnp, medicalRecords) ||
      medicalRecords.find(
        (r) =>
          r.patientName &&
          cleanOld &&
          (r.patientName.toLowerCase().trim() === cleanOld.toLowerCase().trim() ||
            normalizePatientName(r.patientName) === normalizePatientName(cleanOld))
      );

    const effectiveOldId = oldRecordId || matchedOldRec?.id || `${cleanOld}_${cleanPhone}`.replace(/\s+/g, "_").toLowerCase();
    const newRecordId = `${cleanNew}_${cleanPhone}`.replace(/\s+/g, "_").toLowerCase();

    // 1. Immediately update currentMedicalRecord if matching
    if (currentMedicalRecord) {
      const matchesCurrent =
        currentMedicalRecord.id === effectiveOldId ||
        (matchedOldRec && currentMedicalRecord.id === matchedOldRec.id) ||
        (currentMedicalRecord.patientName &&
          (currentMedicalRecord.patientName.trim().toLowerCase() === cleanOld.toLowerCase() ||
            normalizePatientName(currentMedicalRecord.patientName) === normalizePatientName(cleanOld)));
      if (matchesCurrent) {
        const updated = {
          ...currentMedicalRecord,
          id: newRecordId,
          patientName: cleanNew,
          updatedAt: now,
        };
        setCurrentMedicalRecord(updated);
      }
    }
    originalPatientNameRef.current = cleanNew;

    // 2. Immediately update activeAppointment if open & matching
    if (activeAppointment) {
      const isOldMatch =
        cleanOld &&
        (activeAppointment.patientName?.trim().toLowerCase() === cleanOld.toLowerCase() ||
          normalizePatientName(activeAppointment.patientName) === normalizePatientName(cleanOld));
      const isPhoneMatch =
        cleanPhone &&
        activeAppointment.patientPhone &&
        normalizePhone(activeAppointment.patientPhone) === normalizePhone(cleanPhone) &&
        (!activeAppointment.patientName ||
          activeAppointment.patientName.trim().toLowerCase() === cleanOld.toLowerCase() ||
          normalizePatientName(activeAppointment.patientName) === normalizePatientName(cleanOld));
      const isCnpMatch = cleanCnp && activeAppointment.patientCnp?.trim() === cleanCnp;

      if (isOldMatch || isPhoneMatch || isCnpMatch || activeAppointment.id === effectiveOldId) {
        setActiveAppointment((prev) => (prev ? { ...prev, patientName: cleanNew } : null));
      }
    }

    // 3. Immediately update appointments state in memory
    const matchedAppIds = new Set<string>();
    setAppointments((prev) =>
      prev.map((app) => {
        const isNameMatch =
          cleanOld &&
          (app.patientName?.trim().toLowerCase() === cleanOld.toLowerCase() ||
            normalizePatientName(app.patientName) === normalizePatientName(cleanOld));
        const isPhoneMatch =
          cleanPhone &&
          app.patientPhone &&
          normalizePhone(app.patientPhone) === normalizePhone(cleanPhone) &&
          (!app.patientName ||
            app.patientName.trim().toLowerCase() === cleanOld.toLowerCase() ||
            normalizePatientName(app.patientName) === normalizePatientName(cleanOld));
        const isCnpMatch = cleanCnp && app.patientCnp && app.patientCnp.trim() === cleanCnp;
        const isActive = activeAppointment && app.id === activeAppointment.id;

        if (isNameMatch || isPhoneMatch || isCnpMatch || isActive) {
          matchedAppIds.add(app.id);
          return { ...app, patientName: cleanNew };
        }
        return app;
      })
    );

    // 4. Immediately update medicalRecords state in memory
    setMedicalRecords((prev) => {
      let found = false;
      const updated = prev.map((rec) => {
        const isIdMatch =
          rec.id === effectiveOldId ||
          (matchedOldRec && rec.id === matchedOldRec.id) ||
          rec.id === newRecordId;
        const isNameMatch =
          cleanOld &&
          (rec.patientName?.trim().toLowerCase() === cleanOld.toLowerCase() ||
            normalizePatientName(rec.patientName) === normalizePatientName(cleanOld));
        const isPhoneMatch =
          cleanPhone &&
          rec.patientPhone &&
          normalizePhone(rec.patientPhone) === normalizePhone(cleanPhone) &&
          (!rec.patientName ||
            rec.patientName.trim().toLowerCase() === cleanOld.toLowerCase() ||
            normalizePatientName(rec.patientName) === normalizePatientName(cleanOld));
        const isCnpMatch = cleanCnp && rec.patientCnp && rec.patientCnp.trim() === cleanCnp;

        if (isIdMatch || isNameMatch || isPhoneMatch || isCnpMatch) {
          found = true;
          return {
            ...rec,
            id: newRecordId,
            patientName: cleanNew,
            updatedAt: now,
          };
        }
        return rec;
      });

      if (!found && matchedOldRec) {
        return [{ ...matchedOldRec, id: newRecordId, patientName: cleanNew, updatedAt: now }, ...prev];
      }
      return updated;
    });

    // 5. Immediately update medicalDocuments state in memory
    setMedicalDocuments((prev) =>
      prev.map((docItem) => {
        const isNameMatch =
          cleanOld &&
          (docItem.patientName?.trim().toLowerCase() === cleanOld.toLowerCase() ||
            normalizePatientName(docItem.patientName) === normalizePatientName(cleanOld));
        const isIdMatch = docItem.patientId === effectiveOldId || (matchedOldRec && docItem.patientId === matchedOldRec.id);
        if (isNameMatch || isIdMatch) {
          return { ...docItem, patientName: cleanNew, patientId: newRecordId };
        }
        return docItem;
      })
    );

    // 6. Background Firestore persistence (non-blocking for instant UI response)
    (async () => {
      try {
        // A) Update or migrate medicalRecords in Firestore
        let baseRecord: any = null;
        let foundOldId = effectiveOldId;

        // Try matchedOldRec.id from memory
        if (matchedOldRec?.id) {
          const snap = await getDoc(doc(db, "medicalRecords", matchedOldRec.id)).catch(() => null);
          if (snap && snap.exists()) {
            baseRecord = snap.data();
            foundOldId = matchedOldRec.id;
          }
        }

        // Try effectiveOldId if not found yet
        if (!baseRecord && effectiveOldId) {
          const snap = await getDoc(doc(db, "medicalRecords", effectiveOldId)).catch(() => null);
          if (snap && snap.exists()) {
            baseRecord = snap.data();
            foundOldId = effectiveOldId;
          }
        }

        // Try querying by patientName
        if (!baseRecord && cleanOld) {
          const qSnap = await getDocs(
            query(collection(db, "medicalRecords"), where("patientName", "==", cleanOld))
          ).catch(() => null);
          if (qSnap && !qSnap.empty) {
            baseRecord = qSnap.docs[0].data();
            foundOldId = qSnap.docs[0].id;
          }
        }

        // Fallback to matched memory record or currentMedicalRecord
        if (!baseRecord && matchedOldRec) {
          baseRecord = matchedOldRec;
          foundOldId = matchedOldRec.id;
        }
        if (!baseRecord && currentMedicalRecord) {
          baseRecord = currentMedicalRecord;
          foundOldId = currentMedicalRecord.id;
        }

        if (baseRecord) {
          const recToSave = removeUndefined({
            ...baseRecord,
            id: newRecordId,
            patientName: cleanNew,
            updatedAt: now,
          });
          await setDoc(doc(db, "medicalRecords", newRecordId), recToSave, { merge: true });
          if (foundOldId && foundOldId !== newRecordId) {
            deleteDoc(doc(db, "medicalRecords", foundOldId)).catch(() => {});
          }
          if (effectiveOldId && effectiveOldId !== newRecordId && effectiveOldId !== foundOldId) {
            deleteDoc(doc(db, "medicalRecords", effectiveOldId)).catch(() => {});
          }
        }

        // B) Update all matching appointments in Firestore
        const appDocIds = new Set<string>(matchedAppIds);
        const appQueries = [
          query(collection(db, "appointments"), where("patientName", "==", cleanOld)),
        ];
        if (cleanOld.toUpperCase() !== cleanOld) {
          appQueries.push(query(collection(db, "appointments"), where("patientName", "==", cleanOld.toUpperCase())));
        }
        if (oldName !== cleanOld) {
          appQueries.push(query(collection(db, "appointments"), where("patientName", "==", oldName)));
        }
        if (cleanPhone) {
          appQueries.push(query(collection(db, "appointments"), where("patientPhone", "==", cleanPhone)));
        }
        if (cleanCnp) {
          appQueries.push(query(collection(db, "appointments"), where("patientCnp", "==", cleanCnp)));
        }

        const appSnaps = await Promise.allSettled(appQueries.map((q) => getDocs(q)));
        appSnaps.forEach((res) => {
          if (res.status === "fulfilled") {
            res.value.docs.forEach((d) => {
              const data = d.data();
              if (
                data.patientName?.trim().toLowerCase() === cleanOld.toLowerCase() ||
                (cleanPhone && normalizePhone(data.patientPhone) === normalizePhone(cleanPhone)) ||
                (cleanCnp && data.patientCnp === cleanCnp)
              ) {
                appDocIds.add(d.id);
              }
            });
          }
        });

        for (const appId of appDocIds) {
          updateDoc(doc(db, "appointments", appId), { patientName: cleanNew }).catch((err) =>
            console.warn("Error updating appointment doc during rename:", appId, err)
          );
        }

        // C) Update glasses_orders in Firestore
        const orderQueries = [
          query(collection(db, "glasses_orders"), where("patientName", "==", cleanOld)),
        ];
        if (cleanOld.toUpperCase() !== cleanOld) {
          orderQueries.push(query(collection(db, "glasses_orders"), where("patientName", "==", cleanOld.toUpperCase())));
        }
        if (cleanPhone) {
          orderQueries.push(query(collection(db, "glasses_orders"), where("patientPhone", "==", cleanPhone)));
        }
        if (effectiveOldId) {
          orderQueries.push(query(collection(db, "glasses_orders"), where("patientId", "==", effectiveOldId)));
        }
        const orderSnaps = await Promise.allSettled(orderQueries.map((q) => getDocs(q)));
        const orderDocIds = new Set<string>();
        orderSnaps.forEach((res) => {
          if (res.status === "fulfilled") {
            res.value.docs.forEach((d) => orderDocIds.add(d.id));
          }
        });
        for (const orderId of orderDocIds) {
          updateDoc(doc(db, "glasses_orders", orderId), {
            patientName: cleanNew,
            patientId: newRecordId,
          }).catch((err) => console.warn("Error updating glasses_order doc:", orderId, err));
        }

        // D) Update medicalDocuments in Firestore
        const docQueries = [
          query(collection(db, "medicalDocuments"), where("patientName", "==", cleanOld)),
        ];
        if (effectiveOldId) {
          docQueries.push(query(collection(db, "medicalDocuments"), where("patientId", "==", effectiveOldId)));
        }
        const docSnaps = await Promise.allSettled(docQueries.map((q) => getDocs(q)));
        const docIds = new Set<string>();
        docSnaps.forEach((res) => {
          if (res.status === "fulfilled") {
            res.value.docs.forEach((d) => docIds.add(d.id));
          }
        });
        for (const mDocId of docIds) {
          updateDoc(doc(db, "medicalDocuments", mDocId), {
            patientName: cleanNew,
            patientId: newRecordId,
          }).catch((err) => console.warn("Error updating medicalDocument doc:", mDocId, err));
        }

        // E) Update reception_alerts in Firestore
        const alertQueries = [
          query(collection(db, "reception_alerts"), where("patientName", "==", cleanOld)),
        ];
        if (effectiveOldId) {
          alertQueries.push(query(collection(db, "reception_alerts"), where("patientId", "==", effectiveOldId)));
        }
        const alertSnaps = await Promise.allSettled(alertQueries.map((q) => getDocs(q)));
        const alertIds = new Set<string>();
        alertSnaps.forEach((res) => {
          if (res.status === "fulfilled") {
            res.value.docs.forEach((d) => alertIds.add(d.id));
          }
        });
        for (const alertId of alertIds) {
          updateDoc(doc(db, "reception_alerts", alertId), {
            patientName: cleanNew,
            patientId: newRecordId,
          }).catch((err) => console.warn("Error updating reception_alert doc:", alertId, err));
        }

        // F) Activity log
        logActivity(
          "Redenumire Pacient",
          `Numele pacientului a fost modificat din "${cleanOld}" în "${cleanNew}" peste tot în aplicație (programări, fișe medicale, comenzi, documente).`
        ).catch(() => {});
      } catch (cloudErr) {
        console.warn("Background rename cloud sync error:", cloudErr);
      }
    })();

    setSuccessMessage(`Numele pacientului a fost actualizat peste tot în sistem: "${cleanNew}"`);
    return true;
  };

  interface UniversalPatientUpdates {
    patientName?: string;
    patientPhone?: string;
    patientCnp?: string;
    patientBirthDate?: string;
    patientSex?: "M" | "F" | string;
    patientAge?: number;
  }

  const syncPatientUniversal = async (
    target: {
      patientName?: string;
      patientPhone?: string;
      patientCnp?: string;
      recordId?: string;
    },
    updates: UniversalPatientUpdates,
  ) => {
    const rawTargetName = (target.patientName || "").trim();
    const cleanTargetName = normalizePatientName(target.patientName);
    const rawTargetPhone = (target.patientPhone || "").trim();
    const cleanTargetPhone = normalizePhone(target.patientPhone);
    const cleanTargetCnp = (target.patientCnp || "").trim();
    const targetRecordId = target.recordId || "";

    const newName = updates.patientName !== undefined ? updates.patientName.trim() : undefined;
    const newPhone = updates.patientPhone !== undefined ? updates.patientPhone.trim() : undefined;
    const newCnp = updates.patientCnp !== undefined ? updates.patientCnp.trim() : undefined;
    let newBirthDate = updates.patientBirthDate !== undefined ? updates.patientBirthDate.trim() : undefined;
    let newSex = updates.patientSex !== undefined ? updates.patientSex : undefined;
    let newAge = updates.patientAge;

    if (newCnp && (!newSex || newSex === "")) {
      const detectedSex = getSexFromCNP(newCnp);
      if (detectedSex) newSex = detectedSex;
    }

    if (newCnp && newCnp.length === 13 && (!newBirthDate || newBirthDate === "")) {
      const s = newCnp[0];
      const yy = newCnp.substring(1, 3);
      const mm = newCnp.substring(3, 5);
      const dd = newCnp.substring(5, 7);
      let century = 0;
      if (s === "1" || s === "2") century = 1900;
      else if (s === "3" || s === "4") century = 1800;
      else if (s === "5" || s === "6") century = 2000;
      const mNum = parseInt(mm, 10);
      const dNum = parseInt(dd, 10);
      if (century > 0 && mNum >= 1 && mNum <= 12 && dNum >= 1 && dNum <= 31) {
        newBirthDate = `${century + parseInt(yy, 10)}-${mm}-${dd}`;
      }
    }

    if (newBirthDate && newAge === undefined) {
      newAge = calculateAge(newBirthDate);
    }

    const now = new Date().toISOString();

    const matchesPatient = (item: {
      id?: string;
      patientName?: string;
      patientPhone?: string;
      patientCnp?: string;
    }) => {
      if (targetRecordId && item.id === targetRecordId) return true;
      const itemCnp = (item.patientCnp || "").trim();
      if (cleanTargetCnp && itemCnp && cleanTargetCnp === itemCnp) return true;
      if (newCnp && itemCnp && newCnp === itemCnp) return true;

      const itemCleanName = normalizePatientName(item.patientName);
      const isNameMatch =
        cleanTargetName &&
        itemCleanName &&
        (cleanTargetName === itemCleanName ||
          item.patientName?.toLowerCase().trim() === rawTargetName.toLowerCase());

      const itemCleanPhone = normalizePhone(item.patientPhone);
      const isPhoneMatch =
        cleanTargetPhone && itemCleanPhone && cleanTargetPhone === itemCleanPhone;

      if (isNameMatch && isPhoneMatch) return true;
      if (cleanTargetCnp && itemCnp && cleanTargetCnp === itemCnp) return true;
      if (isNameMatch && (!cleanTargetPhone || !itemCleanPhone)) return true;
      if (isPhoneMatch && (!cleanTargetName || !itemCleanName)) return true;

      return false;
    };

    // 1. Instantly update currentMedicalRecord if matches
    if (currentMedicalRecord && matchesPatient(currentMedicalRecord)) {
      setCurrentMedicalRecord({
        ...currentMedicalRecord,
        ...(newName !== undefined ? { patientName: newName } : {}),
        ...(newPhone !== undefined ? { patientPhone: newPhone } : {}),
        ...(newCnp !== undefined ? { patientCnp: newCnp } : {}),
        ...(newBirthDate !== undefined ? { patientBirthDate: newBirthDate } : {}),
        ...(newSex !== undefined ? { patientSex: newSex as any } : {}),
        ...(newAge !== undefined ? { patientAge: newAge } : {}),
        updatedAt: now,
      });
    }

    // 2. Instantly update activeAppointment if matches
    if (activeAppointment && matchesPatient(activeAppointment)) {
      setActiveAppointment((prev) =>
        prev
          ? {
              ...prev,
              ...(newName !== undefined ? { patientName: newName } : {}),
              ...(newPhone !== undefined ? { patientPhone: newPhone } : {}),
              ...(newCnp !== undefined ? { patientCnp: newCnp } : {}),
              ...(newBirthDate !== undefined ? { patientBirthDate: newBirthDate } : {}),
              ...(newSex !== undefined ? { patientSex: newSex as any } : {}),
              ...(newAge !== undefined ? { patientAge: newAge } : {}),
            }
          : null,
      );
    }

    // 3. Instantly update appointments in memory
    const matchedAppIds: string[] = [];
    setAppointments((prev) =>
      prev.map((app) => {
        if (matchesPatient(app)) {
          matchedAppIds.push(app.id);
          return {
            ...app,
            ...(newName !== undefined ? { patientName: newName } : {}),
            ...(newPhone !== undefined ? { patientPhone: newPhone } : {}),
            ...(newCnp !== undefined ? { patientCnp: newCnp } : {}),
            ...(newBirthDate !== undefined ? { patientBirthDate: newBirthDate } : {}),
            ...(newSex !== undefined ? { patientSex: newSex as any } : {}),
            ...(newAge !== undefined ? { patientAge: newAge } : {}),
            updatedAt: now,
          };
        }
        return app;
      }),
    );

    // 4. Instantly update medicalRecords in memory
    const matchedRecIds: string[] = [];
    setMedicalRecords((prev) =>
      prev.map((rec) => {
        if (matchesPatient(rec)) {
          matchedRecIds.push(rec.id);
          return {
            ...rec,
            ...(newName !== undefined ? { patientName: newName } : {}),
            ...(newPhone !== undefined ? { patientPhone: newPhone } : {}),
            ...(newCnp !== undefined ? { patientCnp: newCnp } : {}),
            ...(newBirthDate !== undefined ? { patientBirthDate: newBirthDate } : {}),
            ...(newSex !== undefined ? { patientSex: newSex as any } : {}),
            ...(newAge !== undefined ? { patientAge: newAge } : {}),
            updatedAt: now,
          };
        }
        return rec;
      }),
    );

    // 5. Asynchronous background Firestore synchronization
    (async () => {
      try {
        const updatePayload: Record<string, any> = { updatedAt: now };
        if (newName !== undefined) updatePayload.patientName = newName;
        if (newPhone !== undefined) updatePayload.patientPhone = newPhone;
        if (newCnp !== undefined) updatePayload.patientCnp = newCnp;
        if (newBirthDate !== undefined) updatePayload.patientBirthDate = newBirthDate;
        if (newSex !== undefined) updatePayload.patientSex = newSex;
        if (newAge !== undefined) updatePayload.patientAge = newAge;

        // A) Update matched medicalRecords in Firestore
        for (const recId of matchedRecIds) {
          try {
            await updateDoc(doc(db, "medicalRecords", recId), removeUndefined(updatePayload));
          } catch (e) {
            console.warn(`Could not sync medicalRecord ${recId}:`, e);
          }
        }

        // B) Update matched appointments in Firestore
        for (const appId of matchedAppIds) {
          try {
            await updateDoc(doc(db, "appointments", appId), removeUndefined(updatePayload));
          } catch (e) {
            console.warn(`Could not sync appointment ${appId}:`, e);
          }
        }

        // C) Update glasses_orders in Firestore
        if (newPhone !== undefined || newName !== undefined) {
          const ordersQuery = query(
            collection(db, "glasses_orders"),
            where("patientName", "==", rawTargetName || (newName || ""))
          );
          const snap = await getDocs(ordersQuery);
          for (const d of snap.docs) {
            try {
              await updateDoc(
                doc(db, "glasses_orders", d.id),
                removeUndefined({
                  ...(newName !== undefined ? { patientName: newName } : {}),
                  ...(newPhone !== undefined ? { patientPhone: newPhone } : {}),
                  updatedAt: now,
                })
              );
            } catch (e) {}
          }
        }
      } catch (cloudErr) {
        console.warn("Universal patient sync background error:", cloudErr);
      }
    })();
  };

  const syncPatientDetailsInDB = async (
    field: "name" | "birthDate" | "sex",
    newValue: string,
  ) => {
    if (!currentMedicalRecord) return;

    if (field === "name") {
      const oldName = (originalPatientNameRef.current || currentMedicalRecord.patientName || "").trim();
      const newName = newValue.trim();
      if (oldName && newName && oldName !== newName) {
        await renamePatientEverywhere(
          oldName,
          newName,
          currentMedicalRecord.patientPhone,
          currentMedicalRecord.patientCnp,
          currentMedicalRecord.id,
        );
        return;
      }
    }

    try {
      const now = new Date().toISOString();
      const phone = (currentMedicalRecord.patientPhone || "").trim();

      const targetName =
        field === "name" ? newValue.trim() : (currentMedicalRecord.patientName || "").trim();
      const targetBirthDate =
        field === "birthDate"
          ? newValue
          : currentMedicalRecord.patientBirthDate || "";
      const targetSex =
        field === "sex" ? newValue : currentMedicalRecord.patientSex || "";

      const calculatedAge = targetBirthDate
        ? calculateAge(targetBirthDate)
        : currentMedicalRecord.patientAge;

      const oldRecordId = currentMedicalRecord.id;
      const oldPatientName = currentMedicalRecord.patientName;
      const newRecordId = `${targetName}_${phone}`
        .replace(/\s+/g, "_")
        .toLowerCase();

      const updatedRecord = {
        ...currentMedicalRecord,
        patientName: targetName,
        patientBirthDate: targetBirthDate,
        patientSex: targetSex as "M" | "F",
        patientAge: calculatedAge ?? currentMedicalRecord.patientAge,
        updatedAt: now,
      };

      if (oldRecordId !== newRecordId) {
        updatedRecord.id = newRecordId;
        await setDoc(
          doc(db, "medicalRecords", newRecordId),
          removeUndefined(updatedRecord),
        );
        try {
          await deleteDoc(doc(db, "medicalRecords", oldRecordId));
        } catch (delErr) {
          console.warn("Could not delete old record:", delErr);
        }
      } else {
        await setDoc(
          doc(db, "medicalRecords", oldRecordId),
          removeUndefined(updatedRecord),
        );
      }

      setCurrentMedicalRecord(updatedRecord);

      setMedicalRecords((prev) => {
        const filtered = prev.filter(
          (r) => r.id !== oldRecordId && r.id !== newRecordId,
        );
        return [updatedRecord, ...filtered];
      });

      if (activeAppointment) {
        const isOldNameMatch =
          oldPatientName &&
          activeAppointment.patientName?.toLowerCase().trim() === oldPatientName.toLowerCase().trim();
        const isNewNameMatch =
          targetName &&
          activeAppointment.patientName?.toLowerCase().trim() === targetName.toLowerCase().trim();
        if (isOldNameMatch || isNewNameMatch || activeAppointment.id === currentMedicalRecord.id) {
          setActiveAppointment((prev) =>
            prev
              ? {
                  ...prev,
                  patientName: targetName,
                  patientBirthDate: targetBirthDate,
                  patientSex: targetSex as "M" | "F" | "",
                  patientAge: calculatedAge ?? prev.patientAge,
                }
              : null,
          );
        }
      }

      try {
        const appointmentsRef = collection(db, "appointments");

        const qByOldName =
          oldPatientName && oldPatientName.trim() !== ""
            ? query(appointmentsRef, where("patientName", "==", oldPatientName))
            : null;

        const qByNewName =
          targetName && targetName.trim() !== "" && targetName !== oldPatientName
            ? query(appointmentsRef, where("patientName", "==", targetName))
            : null;

        const [snapOldName, snapNewName] = await Promise.all([
          qByOldName ? getDocs(qByOldName) : null,
          qByNewName ? getDocs(qByNewName) : null,
        ]);

        const uniqueDocs = new Map<string, any>();
        if (snapOldName) {
          snapOldName.docs.forEach((d) => uniqueDocs.set(d.id, d.data()));
        }
        if (snapNewName) {
          snapNewName.docs.forEach((d) => uniqueDocs.set(d.id, d.data()));
        }
        if (activeAppointment?.id) {
          const appDoc = appointments.find((a) => a.id === activeAppointment.id);
          if (appDoc && (appDoc.patientName?.toLowerCase().trim() === oldPatientName?.toLowerCase().trim() || appDoc.patientName?.toLowerCase().trim() === targetName?.toLowerCase().trim())) {
            uniqueDocs.set(activeAppointment.id, appDoc);
          }
        }

        const updatePromises = Array.from(uniqueDocs.keys()).map((docId) =>
          updateDoc(
            doc(db, "appointments", docId),
            removeUndefined({
              patientName: targetName,
              patientBirthDate: targetBirthDate,
              patientSex: targetSex,
              patientAge: calculatedAge ?? uniqueDocs.get(docId)?.patientAge,
            }),
          ),
        );
        await Promise.all(updatePromises);

        setAppointments((prev) =>
          prev.map((app) => {
            const isOldNameMatch =
              oldPatientName && app.patientName?.toLowerCase().trim() === oldPatientName.toLowerCase().trim();
            const isNewNameMatch =
              targetName && app.patientName?.toLowerCase().trim() === targetName.toLowerCase().trim();
            const isActiveMatch =
              activeAppointment && app.id === activeAppointment.id && (isOldNameMatch || isNewNameMatch);

            if (
              isOldNameMatch ||
              isNewNameMatch ||
              isActiveMatch
            ) {
              return {
                ...app,
                patientName: targetName,
                patientBirthDate: targetBirthDate,
                patientSex: (targetSex as any) || app.patientSex,
                patientAge: calculatedAge ?? app.patientAge,
              };
            }
            return app;
          }),
        );
      } catch (err) {
        console.warn("Could not sync with appointments collection:", err);
      }
    } catch (err) {
      console.error("Error syncing patient details:", err);
    }
  };

  const [patientName, setPatientName] = useState("");
  const [patientAge, setPatientAge] = useState("");
  const [patientBirthDate, setPatientBirthDate] = useState("");
  const [patientPhone, setPatientPhone] = useState("");
  const [patientCnp, setPatientCnp] = useState("");
  const [faraTelefon, setFaraTelefon] = useState(true);
  const [hasStoredPhone, setHasStoredPhone] = useState(false);
  const [patientSex, setPatientSex] = useState<"M" | "F" | "">("");
  const [patientNotes, setPatientNotes] = useState("");
  const patientNameInputRef = useRef<HTMLInputElement>(null);
  const patientPhoneInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (isBookingModalOpen || isNewPatientFromSearchModalOpen) {
      setBookingError(null);
      setTimeout(() => {
        patientNameInputRef.current?.focus();
      }, 100);
    }
  }, [isBookingModalOpen, isNewPatientFromSearchModalOpen]);


  useEffect(() => {
    const seedAndCleanupUsers = async () => {
      try {
        const clinicDocSnap = await getDoc(doc(db, "clinic_config", "main")).catch(() => null);
        if (clinicDocSnap && !clinicDocSnap.data()?.usersSeeded) {
          for (const [id, data] of Object.entries(USERS_DATA)) {
            const userDocRef = doc(db, "users", id);
            await setDoc(
              userDocRef,
              {
                name: data.name,
                role: data.role,
                pass: data.pass,
              },
              { merge: true },
            ).catch(() => {});
          }
          await setDoc(
            doc(db, "clinic_config", "main"),
            { usersSeeded: true },
            { merge: true },
          ).catch(() => {});
        }
      } catch (err: any) {
        if (!err?.message?.toLowerCase().includes("quota")) {
          console.error("Seeding error:", err);
        }
      }
    };
    seedAndCleanupUsers();
  }, []);

  // Sincronizare în timp real (real-time push synchronization) a datelor din Firebase
  useEffect(() => {
    // 1. Users real-time listener (always active to keep user list clean)
    const unsubUsers = onSnapshot(
      collection(db, "users"),
      (snapshot) => {
        const dbUsers = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        })) as any[];
        const cleanUsers = deduplicateUsers(dbUsers);
        setAvailableUsers(cleanUsers);
      },
      (error) => {
        handleFirestoreError(error, OperationType.GET, "users");
      }
    );

    if (!profile) {
      setAppointments([]);
      setConfigs([]);
      setMedicalRecords([]);
      setMedicalDocuments([]);
      return () => {
        unsubUsers();
      };
    }

    // 2. Appointments (Smart / Lazy Loading)
    // Se încarcă doar ultimele 30 de zile și programările viitoare la pornire.
    // Programările vechi din arhivă sunt descărcate automat la navigarea în calendar sau la căutare.
    const thirtyDaysAgoISO = subDays(startOfDay(new Date()), 30).toISOString();
    const unsubAppointments = onSnapshot(
      query(
        collection(db, "appointments"),
        where("startTime", ">=", thirtyDaysAgoISO),
      ),
      (snapshot) => {
        setAppointments((prev) => {
          const fresh = snapshot.docs.map(
            (doc) => ({ id: doc.id, ...doc.data() }) as Appointment,
          );
          const freshIds = new Set(fresh.map((a) => a.id));
          const preservedOlder = prev.filter(
            (a) => !freshIds.has(a.id) && a.startTime < thirtyDaysAgoISO,
          );
          return [...fresh, ...preservedOlder];
        });
      },
      (error) => {
        handleFirestoreError(error, OperationType.GET, "appointments");
      }
    );

    // 3. Configs
    const unsubConfigs = onSnapshot(
      collection(db, "configs"),
      (snapshot) => {
        const rawDocs = snapshot.docs.map(
          (doc) => ({ id: doc.id, ...doc.data() }) as ScheduleConfig,
        );
        // Deduplicate by doctorId, prioritizing canonical doc ID (doc.id === doc.doctorId)
        const docMap = new Map<string, ScheduleConfig>();
        rawDocs.forEach((c) => {
          const docId = c.doctorId || c.id;
          if (docId && !docMap.has(docId)) {
            docMap.set(docId, c);
          }
        });
        rawDocs.forEach((c) => {
          if (c.doctorId && c.id === c.doctorId) {
            docMap.set(c.doctorId, c);
          }
        });
        const deduplicated = Array.from(docMap.values());
        setConfigs(deduplicated);
        try {
          localStorage.setItem("clinic_doctor_configs", JSON.stringify(deduplicated));
        } catch {
          // ignore quota
        }
      },
      (error) => {
        handleFirestoreError(error, OperationType.GET, "configs");
      }
    );

    // 4. Medical Records (Smart / Lazy Loading)
    // Descarcă la pornire doar cele mai recente fișe (limit 120), prevenind blocarea la startup.
    // Toate fișele vechi din arhivă sunt aduse automat în milisecunde la căutare după nume, telefon sau CNP.
    const unsubMedicalRecords = onSnapshot(
      query(collection(db, "medicalRecords"), limit(120)),
      (snapshot) => {
        setMedicalRecords((prev) => {
          const fresh = snapshot.docs.map(
            (doc) => ({ id: doc.id, ...doc.data() }) as MedicalRecord,
          );
          const freshIds = new Set(fresh.map((r) => r.id));
          const preservedOlder = prev.filter((r) => !freshIds.has(r.id));
          return [...fresh, ...preservedOlder];
        });
      },
      (error) => {
        handleFirestoreError(error, OperationType.GET, "medicalRecords");
      }
    );

    // 5. Medical Documents
    const unsubMedicalDocuments = onSnapshot(
      collection(db, "medicalDocuments"),
      (snapshot) => {
        const docs = snapshot.docs.map((doc) => ({ id: doc.id, ...doc.data() }));
        setMedicalDocuments(docs.filter((d: any) => !d.isDeleted));
      },
      (error) => {
        handleFirestoreError(error, OperationType.GET, "medicalDocuments");
      }
    );

    // 6. Frame Stock
    const unsubFrameStock = onSnapshot(
      collection(db, "frame_stock"),
      (snapshot) => {
        setFrameStockList(
          snapshot.docs.map(
            (doc) => ({ id: doc.id, ...doc.data() }) as FrameStockItem
          )
        );
      },
      (error) => {
        handleFirestoreError(error, OperationType.GET, "frame_stock");
      }
    );

    return () => {
      unsubUsers();
      unsubAppointments();
      unsubConfigs();
      unsubMedicalRecords();
      unsubMedicalDocuments();
      unsubFrameStock();
    };
  }, [profile]);

  useEffect(() => {
    if (!googleUser || !googleUser.email) {
      setLoginLockData({ failedAttempts: 0, blockedUntil: 0 });
      return;
    }

    const emailKey = googleUser.email.toLowerCase().replace(/[^a-z0-9]/g, "_");

    try {
      const savedAttempts = localStorage.getItem(`clinic_login_failed_attempts_${emailKey}`);
      const savedBlockedUntil = localStorage.getItem(`clinic_login_blocked_until_${emailKey}`);
      const attempts = savedAttempts ? parseInt(savedAttempts, 10) : 0;
      const blockedUntil = savedBlockedUntil ? parseInt(savedBlockedUntil, 10) : 0;
      setLoginLockData({ failedAttempts: attempts, blockedUntil });
    } catch {
      // ignore
    }

    const unsubLock = onSnapshot(
      doc(db, "settings", `login_lock_${emailKey}`),
      (snapshot) => {
        if (snapshot.exists()) {
          const data = snapshot.data();
          const attempts = typeof data.failedAttempts === "number" ? data.failedAttempts : 0;
          const blockedUntil = typeof data.blockedUntil === "number" ? data.blockedUntil : 0;
          setLoginLockData({ failedAttempts: attempts, blockedUntil });
          try {
            localStorage.setItem(`clinic_login_failed_attempts_${emailKey}`, attempts.toString());
            localStorage.setItem(`clinic_login_blocked_until_${emailKey}`, blockedUntil.toString());
          } catch (e) {
            console.error(e);
          }
        } else {
          setLoginLockData({ failedAttempts: 0, blockedUntil: 0 });
          try {
            localStorage.setItem(`clinic_login_failed_attempts_${emailKey}`, "0");
            localStorage.setItem(`clinic_login_blocked_until_${emailKey}`, "0");
          } catch (e) {
            console.error(e);
          }
        }
      },
      (error) => {
        if (!error.message?.toLowerCase().includes("quota")) {
          console.error("Eroare la ascultarea starii de blocare login:", error);
        }
      }
    );
    return () => unsubLock();
  }, [googleUser]);

