    doc.text(`B.I./C.I. seria`, 10, y);
    drawDottedLine(32, 50, y);
    doc.text(documentForm.patientSeries || "", 34, y - 2);
    doc.text(`nr.`, 52, y);
    drawDottedLine(57, 77, y);
