                                        setFaraTelefon(!app.patientPhone);
                                        setHasStoredPhone(!!app.patientPhone);
                                        setPatientSex(app.patientSex || "");
                                        setBookingError(null);
                                        setIsNewOrderPatientModalOpen(true);
